['canvasSmaller','canvasLarger','canvasRotateLeft','canvasRotateRight'].forEach(id=>{const old=$('#'+id).onclick;$('#'+id).onclick=()=>{if(selectedCanvasText&&!selectedCanvasText.classList.contains('user-canvas-object')){syncSelectionControls();if(id==='canvasSmaller')$('#elementScale').value=Number($('#elementScale').value)-10;if(id==='canvasLarger')$('#elementScale').value=Number($('#elementScale').value)+10;if(id==='canvasRotateLeft')$('#elementAngle').value=Number($('#elementAngle').value)-5;if(id==='canvasRotateRight')$('#elementAngle').value=Number($('#elementAngle').value)+5;applyPrecision()}else old()}});
updateHistoryButtons();
// Preserve layer order/visibility in reloads and exported projects, including added objects.
const snapshotBeforeArrangement=projectSnapshot;projectSnapshot=async()=>{const s=await snapshotBeforeArrangement(),custom=[...document.querySelectorAll('.user-canvas-object')];s.layerArrangement=layerItems.map(item=>({key:item.kind==='custom'?custom.indexOf(item.el):item.kind==='group'?(item.el.classList.contains('spread-title')?'title':'name'):item.kind,custom:item.kind==='custom',label:item.label,hidden:item.hidden,style:item.el.getAttribute('style')}));return s};
const restoreBeforeArrangement=restoreProject;restoreProject=function(s){restoreBeforeArrangement(s);if(!s?.layerArrangement)return;const custom=[...document.querySelectorAll('.user-canvas-object')],all=[...layerItems],ordered=[];s.layerArrangement.forEach(v=>{const item=all.find(item=>v.custom?item.el===custom[v.key]:v.key==='title'?item.el.classList.contains('spread-title'):v.key==='name'?item.el.classList.contains('spread-name'):item.kind===v.key);if(item){item.label=v.label;item.hidden=v.hidden;item.el.setAttribute('style',v.style||'');ordered.push(item)}});all.forEach(item=>{if(!ordered.includes(item))ordered.push(item)});layerItems.splice(0,layerItems.length,...ordered);refreshLayerList()};
// Decorative motion is independent of user image transforms and pauses while editing.
const atmosphere=document.createElement('div');atmosphere.className='detail-atmosphere';atmosphere.setAttribute('aria-hidden','true');for(let i=0;i<12;i++){const petal=document.createElement('i');petal.style.cssText=`--petal-x:${(i*37+5)%100}%;--petal-size:${10+i%4*5}px;--petal-time:${12+i%5*2}s;--petal-delay:${1.8+i*.9}s`;atmosphere.append(petal)}$('#posterStage').append(atmosphere);const detailLight=document.createElement('div');detailLight.className='detail-light';detailLight.setAttribute('aria-hidden','true');$('#posterStage').append(detailLight);document.querySelectorAll('.spread-sparkles i').forEach((el,i)=>el.style.setProperty('--spark-order',i));
const motionToggle=document.createElement('button');motionToggle.id='detailMotionToggle';motionToggle.textContent='모션 끄기';motionToggle.setAttribute('aria-pressed','true');focusDialog.append(motionToggle);motionToggle.onclick=()=>{const off=focusDialog.classList.toggle('motion-off');motionToggle.textContent=off?'모션 켜기':'모션 끄기';motionToggle.setAttribute('aria-pressed',!off)};
$('#replayReveal').setAttribute('aria-label','상세 연출 다시 보기');$('#replayReveal').title='상세 연출 다시 보기';const replayBeforeDetail=$('#replayReveal').onclick;$('#replayReveal').onclick=()=>{if(!focusDialog.classList.contains('poster-mode'))return replayBeforeDetail();focusDialog.classList.remove('motion-off');motionToggle.textContent='모션 끄기';motionToggle.setAttribute('aria-pressed','true');requestAnimationFrame(()=>{$('#posterStage').getAnimations({subtree:true}).forEach(animation=>{animation.currentTime=0;animation.play()})})};
// Reference-driven cut / hold / reveal timeline. No artwork is flattened or duplicated in saved data.
const cinematic=document.createElement('div');cinematic.className='detail-cinematic';cinematic.hidden=true;cinematic.setAttribute('aria-hidden','true');cinematic.innerHTML='<div class="cinema-slice"></div><div class="cinema-slice"></div><div class="cinema-slice"></div><div class="cinema-caption"><small></small><strong></strong></div><div class="cinema-rule"></div>';$('#posterStage').append(cinematic);
let sequenceAnimations=[],sequenceTimer=null,sequenceWasPoster=false,sequenceWasEditing=false;
function stopDetailSequence(){clearTimeout(sequenceTimer);sequenceAnimations.forEach(a=>a.cancel());sequenceAnimations=[];cinematic.hidden=true;$('#posterStage').classList.remove('detail-sequence-running')}
function sequenceAnimate(el,frames,duration,delay=0,easing='cubic-bezier(.16,1,.3,1)'){if(!el)return;const a=el.animate(frames,{duration,delay,easing,fill:'both'});sequenceAnimations.push(a);return a}
function playDetailSequence(){stopDetailSequence();if(!focusDialog.open||!focusDialog.classList.contains('poster-mode')||focusDialog.classList.contains('canvas-editing')||focusDialog.classList.contains('motion-off')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const stage=$('#posterStage'),character=chars[selected],close=sceneFor(character,'close'),main=sceneFor(character,'poster'),source=!close.empty?close:!main.empty?main:null;
cinematic.querySelectorAll('.cinema-slice').forEach(el=>{el.style.backgroundImage=source?`url("${source.url||'reference.png'}")`:'none';el.style.backgroundSize=source&&!source.url?'auto 360%':'cover'});cinematic.style.setProperty('--cinema-position',source?(source.url?`${source.position??50}% ${source.positionY??35}%`:`${[0,33,66,100][source.sample]}% 42%`):'50% 35%');cinematic.querySelector('small').textContent=`CHARACTER JOURNAL / ${String(selected+1).padStart(2,'0')}`;cinematic.querySelector('strong').textContent=character.name||$('#detailTitle').value||'Your story';cinematic.hidden=false;stage.classList.add('detail-sequence-running');
// Establish the character for a beat, then move three angled planes in opposing directions.
cinematic.querySelectorAll('.cinema-slice').forEach((el,i)=>{const distance=i===1?'-110%':'110%';sequenceAnimate(el,[{transform:'scale(1.075)',opacity:1,offset:0},{transform:'scale(1.025)',opacity:1,offset:.39},{transform:`translateY(${distance}) scale(1.025)`,opacity:1,offset:1}],1050+i*70,0,'cubic-bezier(.76,0,.24,1)')});
sequenceAnimate(cinematic.querySelector('.cinema-caption'),[{opacity:0,translate:'0 16px',offset:0},{opacity:1,translate:'0 0',offset:.2},{opacity:1,translate:'0 0',offset:.62},{opacity:0,translate:'-35px 0',offset:1}],760,80,'cubic-bezier(.2,.65,.25,1)');sequenceAnimate(cinematic.querySelector('.cinema-rule'),[{scale:'0 1',opacity:0},{scale:'1 1',opacity:1}],420,120);
// The final layout lands as grouped planes, with a clear leading subject and a later title.
sequenceAnimate(stage.querySelector('.spread-main'),[{translate:'7% 0',opacity:0,offset:0},{translate:'-.6% 0',opacity:1,offset:.78},{translate:'0 0',opacity:1,offset:1}],900,430);
sequenceAnimate(stage.querySelector('.spread-close'),[{translate:'8% -8%',transform:'rotate(6deg)',opacity:0},{translate:'0 0',transform:'rotate(0deg)',opacity:1}],780,570);
sequenceAnimate(stage.querySelector('.spread-photo'),[{translate:'-10% 12%',transform:'rotate(-8deg)',opacity:0},{translate:'0 0',transform:'rotate(0deg)',opacity:1}],680,810);
sequenceAnimate(stage.querySelector('.spread-extra'),[{translate:'7% 8%',opacity:0},{translate:'0 0',opacity:1}],720,930);
sequenceAnimate($('#spreadTitle'),[{clipPath:'inset(-30% 100% -30% -10%)',translate:'-24px 0',opacity:0},{clipPath:'inset(-30% -10% -30% -10%)',translate:'0 0',opacity:1}],850,810);
[stage.querySelector('.spread-title small'),$('#spreadNote'),stage.querySelector('.spread-name'),stage.querySelector('.spread-memo'),stage.querySelector('.spread-handwritten')].forEach((el,i)=>sequenceAnimate(el,[{opacity:0,translate:'0 12px'},{opacity:1,translate:'0 0'}],520,1120+i*95));
sequenceAnimate(stage.querySelector('.spread-floral-overlay'),[{opacity:0},{opacity:1}],850,720);sequenceAnimate(stage.querySelector('.spread-ribbon'),[{clipPath:'inset(0 100% 0 0)',opacity:0},{clipPath:'inset(0 0 0 0)',opacity:1}],1000,1020);stage.querySelectorAll('.spread-sparkles i').forEach((el,i)=>sequenceAnimate(el,[{scale:'.35',opacity:0},{scale:'1.12',opacity:1,offset:.65},{scale:'1',opacity:1}],500,1320+i*90));
sequenceTimer=setTimeout(stopDetailSequence,2250)}
new MutationObserver(()=>{const poster=focusDialog.classList.contains('poster-mode'),editing=focusDialog.classList.contains('canvas-editing');if(!focusDialog.open||!poster||editing||focusDialog.classList.contains('motion-off'))stopDetailSequence();else if(poster&&!sequenceWasPoster)playDetailSequence();sequenceWasPoster=poster;sequenceWasEditing=editing}).observe(focusDialog,{attributes:true,attributeFilter:['class','open']});
$('#replayReveal').onclick=()=>{focusDialog.classList.remove('motion-off');motionToggle.textContent='모션 끄기';motionToggle.setAttribute('aria-pressed','true');playDetailSequence()};motionToggle.onclick=()=>{const off=focusDialog.classList.toggle('motion-off');motionToggle.textContent=off?'모션 켜기':'모션 끄기';motionToggle.setAttribute('aria-pressed',!off);if(off)stopDetailSequence();else playDetailSequence()};

matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{if(e.matches)stopDetailSequence()});
